<template>
  <BaseDialog :show="true" :z-index="40" :title="t('marketplace.replaceCredentials')" :close-on-escape="!busy" :close-on-click-outside="!busy" :show-close-button="!busy" @close="close">
    <form class="space-y-4" @submit.prevent="submit">
      <p class="text-sm text-gray-500">{{ t('marketplace.reauthorizationReview') }}</p>
      <label v-if="['api_key', 'apikey'].includes(account.type) && (!unknown || unknown === 'credential')" class="block text-sm">{{ t('marketplace.apiKey') }}<input v-model="key" data-test="credential-key" type="password" autocomplete="off" class="input mt-1 w-full" /></label>
      <template v-if="account.type === 'oauth' && session && !unknown"><a :href="authUrl" target="_blank" rel="noopener noreferrer" class="text-primary-600 underline">{{ t('marketplace.openAuthorization') }}</a><label class="block text-sm">{{ t('marketplace.callbackUrl') }}<input v-model="callback" data-test="credential-callback" autocomplete="off" class="input mt-1 w-full" /></label></template>
      <template v-if="unknown === 'authorization' && authStatus === 'pending'"><label class="block text-sm">{{ t('marketplace.callbackUrl') }}<input v-model="callback" data-test="recovery-callback" autocomplete="off" class="input mt-1 w-full" /></label><button type="button" data-test="retry-authorization" class="btn btn-secondary" :disabled="busy || !callback" @click="retryAuthorization">{{ t('marketplace.retrySameOperation') }}</button></template><p v-if="(unknown === 'authorization' && session) || (unknown === 'credential' && operationKey)" class="break-all text-sm">{{ t('marketplace.operationReference') }}: {{ unknown === 'authorization' ? session : operationKey }}</p><p v-if="unknown" role="alert" class="text-sm text-amber-600">{{ t(unknown === 'authorization' ? 'marketplace.authorizationUnknown' : 'marketplace.operationUnknown') }}</p>
      <button v-if="unknown" type="button" data-test="check-credential" class="btn btn-secondary" :disabled="busy" @click="check">{{ t('marketplace.checkStatus') }}</button>
      <button v-if="unknown === 'credential'" type="button" data-test="retry-credential" class="btn btn-secondary" :disabled="busy || !key" @click="retryCredential">{{ t('marketplace.retrySameOperation') }}</button><p v-if="error" role="alert" class="text-sm text-red-600">{{ error }}</p>
      <div class="flex justify-end gap-2"><button type="button" class="btn btn-secondary" :disabled="busy" @click="close">{{ t('common.cancel') }}</button><button class="btn btn-primary" :disabled="locked || (['api_key', 'apikey'].includes(account.type) && !key)">{{ ['api_key', 'apikey'].includes(account.type) ? t('marketplace.replaceCredentials') : session ? t('marketplace.completeAuthorization') : t('marketplace.startAuthorization') }}</button></div>
    </form>
  </BaseDialog>
</template>
<script setup lang="ts">
import { computed, onUnmounted, ref, watch } from 'vue'
import { onBeforeRouteLeave, onBeforeRouteUpdate } from 'vue-router'
import { useI18n } from 'vue-i18n'
import BaseDialog from '@/components/common/BaseDialog.vue'
import { replaceCredentials, getSupplierOperation, createAuthorization, completeAuthorization, getAuthorizationStatus } from '@/api/supplier'
import type { SupplierAccount } from '@/types/marketplace'
const props = defineProps<{ account: SupplierAccount; ownerId?: number }>(); const emit = defineEmits<{ close: []; saved: [] }>(); const { t } = useI18n()
const key = ref(''); const busy = ref(false); const unknown = ref<'' | 'authorization' | 'credential'>(''); const session = ref(''); const authUrl = ref(''); const callback = ref(''); const operationKey = ref(''); const error = ref(''); const authStatus = ref('')
let savedVersion = props.account.offer.version, generation = 0, disposed = false
function storage(owner: number | undefined, id: number) { return owner ? `supplier-credential-operation:${owner}:${id}` : '' }
function persist(owner: number | undefined, id: number, value: object) { const slot = storage(owner, id); if (slot) sessionStorage.setItem(slot, JSON.stringify(value)) }
function clearOperation(owner = props.ownerId, id = props.account.id) { const slot = storage(owner, id); if (slot) sessionStorage.removeItem(slot) }
function token() { const owner = props.ownerId, id = props.account.id, epoch = generation; return { owner, id, active: () => !disposed && generation === epoch && props.ownerId === owner && props.account.id === id } }
watch(() => [props.ownerId, props.account.id] as const, ([owner, id]) => { generation++; busy.value = false; unknown.value = ''; session.value = ''; authUrl.value = ''; callback.value = ''; operationKey.value = ''; key.value = ''; error.value = ''; authStatus.value = ''; savedVersion = props.account.offer.version; try { const slot = storage(owner, id); const saved = slot ? JSON.parse(sessionStorage.getItem(slot) || 'null') : null; if (saved?.kind === 'credential' && typeof saved.key === 'string' && typeof saved.version === 'number') { operationKey.value = saved.key; savedVersion = saved.version; unknown.value = 'credential' } else if (saved?.kind === 'authorization' && typeof saved.session === 'string') { session.value = saved.session; unknown.value = 'authorization' } } catch { /* Ignore invalid recovery metadata. */ } }, { immediate: true, flush: 'sync' })
const locked = computed(() => busy.value || !!unknown.value)
onBeforeRouteLeave(() => !busy.value)
onBeforeRouteUpdate(() => !busy.value)
function beforeUnload(event: BeforeUnloadEvent) { if (busy.value) { event.preventDefault(); event.returnValue = '' } }
window.addEventListener('beforeunload', beforeUnload)
onUnmounted(() => { disposed = true; generation++; window.removeEventListener('beforeunload', beforeUnload); key.value = ''; callback.value = '' })
function close() { if (!busy.value) { key.value = ''; callback.value = ''; emit('close') } }
async function submit() {
  if (locked.value) return; const context = token(); busy.value = true; error.value = ''; let phase: 'key' | 'start' | 'complete' | 'local' = 'local'
  try {
    if (['api_key', 'apikey'].includes(props.account.type)) { if (!key.value) return; operationKey.value ||= crypto.randomUUID(); savedVersion = props.account.offer.version; persist(context.owner, context.id, { kind: 'credential', key: operationKey.value, version: savedVersion }); phase = 'key'; await replaceCredentials(context.id, { api_key: key.value, expected_version: savedVersion }, operationKey.value); if (!context.active()) return; key.value = ''; clearOperation(context.owner, context.id); emit('saved'); return }
    if (!session.value) { phase = 'start'; const result = await createAuthorization({ purpose: 'reauthorize', provider: props.account.platform, account_id: context.id }); if (!context.active()) return; const url = new URL(result.auth_url); if (!['http:', 'https:'].includes(url.protocol)) throw new Error('invalid authorization URL'); session.value = result.session_id; authUrl.value = url.href; return }
    const url = new URL(callback.value); const state = url.searchParams.get('state'); const code = url.searchParams.get('code'); if (!state || !code) throw new Error('invalid callback')
    persist(context.owner, context.id, { kind: 'authorization', session: session.value }); phase = 'complete'; const result = await completeAuthorization(session.value, { state, code, purpose: 'reauthorize', account_id: context.id }); if (!context.active()) return; if (result.account_id !== context.id) throw new Error('unexpected account'); callback.value = ''; clearOperation(context.owner, context.id); emit('saved')
  } catch (e) { if (!context.active()) return; key.value = ''; callback.value = ''; if (phase === 'complete') unknown.value = 'authorization'; else if (phase === 'key') unknown.value = 'credential'; else error.value = t('marketplace.authorizationFailed') }
  finally { if (context.active()) busy.value = false }
  if (context.active() && unknown.value === 'authorization') await check()
}
async function retryCredential() { if (busy.value || unknown.value !== 'credential' || !key.value || !operationKey.value) return; const context = token(); busy.value = true; try { await replaceCredentials(context.id, { api_key: key.value, expected_version: savedVersion }, operationKey.value); if (!context.active()) return; clearOperation(context.owner, context.id); key.value = ''; unknown.value = ''; emit('saved') } catch { if (context.active()) { key.value = ''; error.value = t('marketplace.operationUnknown') } } finally { if (context.active()) busy.value = false } }
async function retryAuthorization() { if (busy.value || unknown.value !== 'authorization' || authStatus.value !== 'pending') return; const context = token(); busy.value = true; try { const url = new URL(callback.value); const state = url.searchParams.get('state'), code = url.searchParams.get('code'); if (!state || !code) throw new Error('invalid callback'); const result = await completeAuthorization(session.value, { state, code, purpose: 'reauthorize', account_id: context.id }); if (!context.active()) return; if (result.account_id !== context.id) throw new Error('unexpected account'); clearOperation(context.owner, context.id); callback.value = ''; unknown.value = ''; emit('saved') } catch { if (context.active()) { callback.value = ''; authStatus.value = ''; error.value = t('marketplace.operationUnknown') } } finally { if (context.active()) busy.value = false } }
async function check() { if (busy.value) return; const context = token(); busy.value = true; try { const result = unknown.value === 'authorization' ? await getAuthorizationStatus(session.value) : await getSupplierOperation(operationKey.value); if (!context.active()) return; authStatus.value = result.status; error.value = ''; if (result.status === 'completed' && (result.account_id === undefined || result.account_id === context.id)) { unknown.value = ''; clearOperation(context.owner, context.id); emit('saved') } else if (result.status === 'failed') { unknown.value = ''; clearOperation(context.owner, context.id); session.value = ''; authUrl.value = ''; operationKey.value = ''; error.value = t('marketplace.authorizationFailed') } else if (result.status === 'needs_review') error.value = t('marketplace.authorizationNeedsReview') } catch { /* Keep the unknown state until the server confirms a result. */ } finally { if (context.active()) busy.value = false } }
</script>
